"""Ansøgning og CV, Gentofte Ejendomme driftsleder."""
import os
from master_design import MasterDoc
R=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def build():
 m=MasterDoc(os.path.join(R,'Shahram_Ajloo_NNE_DepartmentManagerEI.docx'),lang='da-DK')
 n='SHAHRAM AJLOO'; t='Driftsleder · ejendomsdrift, mennesker og samarbejde'; c='+45 93 99 95 14 · ajlooshahram@gmail.com · linkedin.com/in/shahramajloo · Måløv'
 m.header_banner(n,t,c);m.meta('Gentofte Ejendomme · Driftsleder · Gentofte Kommune')
 m.para('**Ansøgning: Når brugeren åbner døren, skal bygningen fungere**',after=60)
 for s in [
 'Kommunens bygninger skal give brugerne rammer, der fungerer i hverdagen. For et selvstyrende driftsteam med mere end 50 lokationer kræver det fælles prioriteringer, fagligt råderum og en løbende dialog med dem, der bruger bygningerne. Driftsledelse skal skabe sammenhæng mellem disse behov og de ressourcer og vedligeholdelsesbudgetter, der er til rådighed.',
 'Jeg vil begynde med at lytte til teamet, eleven og lederne på lokationerne. Sammen kan vi skabe et overblik over opgaver, aftaler, kritiske forhold og kommende vedligehold, så vi kan prioritere efter sikkerhed, brugernes behov og konsekvens ved udsættelse. Teamet skal have plads til at tilrettelægge arbejdet; hvor retning, ansvar eller prioritet er uklar, er det lederens opgave at træffe en tydelig beslutning og følge op.',
 'Budgettet skal understøtte de valg. Jeg vil sammen med teamet og relevante kolleger følge forbrug og forventede udgifter mod vedligeholdelsesbudgettet, gøre afvigelser synlige og drøfte ændringer, før rammen overskrides. Ved mindre vedligeholdelsesprojekter vil jeg bidrage med driftsfaglig sparring om brugernes hverdag, adgang til anlæg, prioritering og en sikker overdragelse.',
 'Jeg har erfaring med drift og vedligeholdelse af ejendomme, ledelse af selvstyrende medarbejdere og ansvar for en ejendomsportefølje på flere lokationer. Omfang og typer af bygninger uddyber jeg gerne ved samtale. Hos ELOHVAC har jeg fuldt resultatansvar og leder fem elektrikere og tre lærlinge; hos BIOFOS arbejdede jeg med forebyggende vedligehold og kritisk drift. Erfaringen med medarbejderudvikling og tekniske anlæg kan understøtte både eleven og det fælles overblik i Gentofte.',
 'Gentofte Kommunes jobløfte beskriver indflydelse på arbejdsrammerne, faglig udvikling og at være sammen om ledelse. Det passer til en tilgang, hvor medarbejdernes viden bruges aktivt, og hvor forventninger til samarbejde på tværs af Drift, Byggeri og Vedligehold aftales tydeligt. Jeg vil gerne drøfte, hvilke forventninger lokationerne har til samarbejdet, og hvor teamet ser de bedste muligheder for at udvikle driften.'
 ]:m.para(s,after=48,line=245)
 m.meta('Med venlig hilsen',after=5);m.meta('Shahram Ajloo · +45 93 99 95 14 · ajlooshahram@gmail.com',after=0)
 m.page_break();m.resume_header(n,t,c,'OPGAVEN — VELFUNGERENDE BYGNINGER OG ET SELVSTYRENDE TEAM')
 m.para('Understøt et selvstyrende team og en ejendomsserviceteknikerelev i drift og vedligehold af mere end 50 lokationer. Skab klare prioriteringer, budgetoverblik og tillidsfulde aftaler med bygningernes ledere og brugere. Erfaring med ejendomsdrift, portefølje på flere lokationer og selvstyrende medarbejdere er bekræftet; konkret omfang og arbejdsgiver er ikke oplyst.',after=35)
 m.section('RETNING, RÅDERUM, RELATIONER')
 for a,b in [('Retning','Aftal mål, prioriteringskriterier, budgetopfølgning og beslutningsveje med team og ledergruppe.'),('Råderum','Lyt til teamets faglige vurderinger, støt eleven og giv medarbejderne indflydelse inden for klare rammer, og følg op på trivsel.'),('Relationer','Afstem forventninger med lokationernes ledere og brugere og følg op på aftaler med Drift, Byggeri og Vedligehold.')]:m.bullet(a,b,after=10)
 m.section('ERHVERVSERFARING')
 jobs=[('Ejer / teknisk direktør / elautoriseret maskinmester','ELOHVAC ApS · København · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Ledelse og service','Leder fem elektrikere og tre lærlinge med daglig planlægning, 1:1 og oplæring; arbejder med elinstallation, styring, ventilation og klimaanlæg.'),('Ressourcer og kvalitet','Tilbud, tidsplaner og kvalitetstjek understøttes af egne værktøjer med over 40 % dokumenteret produktivitetsløft.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Projekter og koordinering','Koordinerede engineering, indkøb og anlæg, fremdrift, økonomi og risiko. FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Planlægning og samarbejde','Daglig planlægning og koordinering af medarbejdere og underentreprenører; tavlemøder og flaskehalsanalyse.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk 24/7-drift',[('Vedligehold og teknisk drift','Forebyggende vedligehold, elektrisk og mekanisk fejlfinding samt standardarbejde og PDCA.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere',[('Team og planlægning','Vagtplanlægning og materialekoordinering; diagnose og reparation af industrielt udstyr.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · København · 2024–nov. 2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden ophørt',[('Udvikling','Ledede tekniske applikationer fra behov og integration til dokumentation og overdragelse.')])]
 for a,b,scope,bullets in jobs:
  m.job(a,b,scope=scope)
  for x,y in bullets:m.bullet(x,y,after=10)
 m.page_break();m.section('UDDANNELSE, METODER OG SPROG')
 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('Køle- og ventilationsteknik','Mercantec AMU · 2021'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Metoder:** Lean og Six Sigma anvendt i praksis, ikke certificeret; PRINCE2 certificeret. **Værktøjer:** Excel, SAP ERP og digitale planlægningsværktøjer. **Sprog:** dansk, engelsk og persisk.',after=20)
 rows=[('Selvstyrende team og personaleansvar','Erfaring med ledelse af selvstyrende medarbejdere er bekræftet; rammer og omfang ikke specificeret. ELOHVAC: otte medarbejdere med 1:1 og oplæring.'),('Ejendomsdrift og flere lokationer','Erfaring med ejendomsdrift og ansvar for en portefølje på flere lokationer er bekræftet. Arbejdsgiver, ejendomstyper og antal er ikke specificeret.'),('Drift og vedligehold af over 50 lokationer','Stillingen omfatter over 50 lokationer; tidligere tilsvarende omfang er ikke angivet. Vil kortlægge behov, opgaver og prioriteringer med teamet.'),('Vedligeholdelsesbudget og økonomi','ELOHVAC: fuldt P&L; Novo: opfølgning på projektøkonomi. Vil følge forbrug og forventede udgifter og afklare afvigelser inden for kommunens rammer.'),('Struktur, ressourcer og prioritering','Ventek-Air: 14 medarbejdere på 11 samtidige projekter, tavlemøder og flaskehalsanalyse. Vil prioritere efter sikkerhed, brugerbehov og konsekvens.'),('Relationer og forventningsafstemning','ELOHVAC: kundekontakt og daglig koordinering. Vil aftale kontakt, serviceniveau og tilbagemelding med ledere og brugere på lokationerne.'),('Vedligeholdelsesprojekter og faglig sparring','BIOFOS: forebyggende vedligehold og fejlfinding; ELOHVAC: el, styring, ventilation og klima. Vil inddrage drift og brugere ved mindre projekter.'),('Eleven og medarbejdernes udvikling','ELOHVAC: oplæring og 1:1 for fem elektrikere og tre lærlinge. Vil aftale læringsmål og støtte med eleven og de relevante fagpersoner.'),('Udvikling og samarbejde på tværs','Novo: 25 specialister på tværs af engineering, indkøb og anlæg. Vil udvikle opgaver, arbejdsgange og samarbejdsaftaler med medarbejdere og kolleger.'),('Tydelig, synlig ledelse og tillid','ELOHVAC: daglig ledelse af otte medarbejdere; Ventek-Air: koordinering af 14. Vil kombinere involvering og fagligt råderum med klare beslutninger.'),('Relevant faglig baggrund','B.Tech og elautoriseret maskinmester; praktisk erfaring med el, ventilation, tekniske anlæg og vedligehold. Bygge- og anlægsfaglig profil er en fordel, ikke et krav.')]
 m.models_table('ROLLEBEHOV — ERFARING OG TILGANG',('Krav i rollen','Erfaring eller foreslået tilgang'),rows,widths=(2600,7746))
 m.section('FØRSTE SKRIDT MED TEAM OG BRUGERE')
 for s in ['Lyt til team, elev og lokationernes ledere; skab overblik over aftaler, opgaver, budget og kritiske behov.','Aftal prioriteringer, ansvar og forventninger; følg budget og tilbagemeldinger med respekt for teamets råderum.','Vælg forbedringer sammen med medarbejdere og kolleger, og følg op på samarbejde og kvalitet i driften.']:m.bullet('',s,after=10)
 m.save(os.path.join(R,'Shahram_Ajloo_Gentofte_DriftslederEjendomme.docx'))
